    // where each bucket has a reference to the next bucket
    if (bucket == null) {
        return;
    }

    Bucket current = this;
    while (current.next != bucket) {
        if (current.next == null) {
            return; // bucket not found in the list
        }
        current = current.next;
    }

    // Insert this bucket before the given bucket
    this.next = bucket;
    current.next = this;
}

