public class ClassFileBuffer {
    private byte[] buffer;
    private int position;

    public ClassFileBuffer(int capacity) {
        this.buffer = new byte[capacity];
        this.position = 0;
    }

    /**
     * Clear and fill the buffer of this {@code ClassFileBuffer} with the supplied byte stream.
     * The read pointer is reset to the start of the byte array.
     */
    public void readFrom(final InputStream in) throws IOException {
        position = 0;
        int bytesRead;
        while ((bytesRead = in.read(buffer, position, buffer.length - position)) != -1) {
            position += bytesRead;
        }
        if (position < buffer.length) {
            throw new IOException("Unexpected end of input stream");
        }
    }
}

