private Map<String, Object> buildContent(JsonObject jsonObject) {
    Map<String, Object> contentMap = new HashMap<>();
    for (Map.Entry<String, JsonElement> entry : jsonObject.entrySet()) {
        String key = entry.getKey();
        JsonElement value = entry.getValue();
        if (value.isJsonObject()) {
            contentMap.put(key, buildContent(value.getAsJsonObject()));
        } else if (value.isJsonArray()) {
            contentMap.put(key, buildArray(value.getAsJsonArray()));
        } else {
            contentMap.put(key, convertJsonElement(value));
        }
    }
    return contentMap;
}

private List<Object> buildArray(JsonArray jsonArray) {
    List<Object> array = new ArrayList<>();
    for (JsonElement element : jsonArray) {
        if (element.isJsonObject()) {
            array.add(buildContent(element.getAsJsonObject()));
        } else if (element.isJsonArray()) {
            array.add(buildArray(element.getAsJsonArray()));
        } else {
            array.add(convertJsonElement(element));
        }
    }
    return array;
}

private Object convertJsonElement(JsonElement element) {
    if (element.isJsonPrimitive()) {
        JsonPrimitive primitive = element.getAsJsonPrimitive();
        if (primitive.isString()) {
            return primitive.getAsString();
        } else if (primitive.isNumber()) {
            return primitive.getAsNumber();
        } else if (primitive.isBoolean()) {
            return primitive.getAsBoolean();
        }
    }
    return null;
}

