public class StringUnescaper {

    public static String unescapeJava(String str) throws Exception {
        if (str == null) {
            return null;
        }

        StringBuilder sb = new StringBuilder();
        int i = 0;
        while (i < str.length()) {
            char c = str.charAt(i);
            if (c == '\\') {
                if (i + 1 < str.length()) {
                    char nextChar = str.charAt(i + 1);
                    switch (nextChar) {
                        case 'n':
                            sb.append('\n');
                            break;
                        case 't':
                            sb.append('\t');
                            break;
                        case 'r':
                            sb.append('\r');
                            break;
                        case 'b':
                            sb.append('\b');
                            break;
                        case 'f':
                            sb.append('\f');
                            break;
                        case '"':
                            sb.append('"');
                            break;
                        case '\'':
                            sb.append('\'');
                            break;
                        case '\\':
                            sb.append('\\');
                            break;
                        default:
                            throw new Exception("Invalid escape sequence: \\" + nextChar);
                    }
                    i += 2;
                } else {
                    throw new Exception("Invalid escape sequence at end of string");
                }
            } else {
                sb.append(c);
                i += 1;
            }
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        try {
            String escaped = "This is a test string with a newline:\\n and a tab:\\t";
            String unescaped = unescapeJava(escaped);
            System.out.println("Escaped: " + escaped);
            System.out.println("Unescaped: " + unescaped);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

