public class UriTemplate {

    private final Pattern pattern;
    private final List<String> variableNames;

    public UriTemplate(String template) {
        // Assume this constructor parses the template and initializes pattern and variableNames
        this.pattern = Pattern.compile(template);
        this.variableNames = new ArrayList<>(); // Extract variable names from the template
    }

    /**
     * Match a URI against the pattern.
     * @param uri the uri to match against the template.
     * @return the match result, otherwise null if no match occurs.
     */
    public final MatchResult match(CharSequence uri) {
        if (uri == null) {
            return null;
        }
        Matcher matcher = pattern.matcher(uri);
        if (matcher.matches()) {
            Map<String, String> variables = new HashMap<>();
            for (int i = 0; i < variableNames.size(); i++) {
                variables.put(variableNames.get(i), matcher.group(i + 1));
            }
            return new MatchResult(variables);
        }
        return null;
    }

    public static class MatchResult {
        private final Map<String, String> variables;

        public MatchResult(Map<String, String> variables) {
            this.variables = variables;
        }

        public Map<String, String> getVariables() {
            return variables;
        }
    }
}

