public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }
    int lastSeparatorIndex = indexOfLastSeparator(filename);
    if (lastSeparatorIndex == -1) {
        lastSeparatorIndex = filename.length();
    }
    int dotIndex = filename.lastIndexOf('.', lastSeparatorIndex);
    if (dotIndex == -1 || dotIndex < lastSeparatorIndex) {
        return -1;
    }
    return dotIndex;
}

private static int indexOfLastSeparator(String filename) {
    if (filename == null) {
        return -1;
    }
    int unixIndex = filename.lastIndexOf('/');
    int windowsIndex = filename.lastIndexOf('\\');
    return Math.max(unixIndex, windowsIndex);
}

